// Registrar sensores que envían mensajes MQTT
let payload = msg.payload;
if (typeof payload === 'string') {
    try {
        payload = JSON.parse(payload);
    } catch(e) {
        return null;
    }
}

// Extraer ID del sensor del mensaje o del topic
const sensorId = payload.sensorId || payload.deviceId || payload.id;
const sensorIp = payload.ip || null;

if (!sensorId) return null;

// Obtener lista de sensores
let sensores = global.get('sensores_conectados') || [];

// Buscar si ya existe
const idx = sensores.findIndex(s => s.id === sensorId);

const sensorData = {
    id: sensorId,
    ip: sensorIp,
    nombre: payload.nombre || sensorId,
    estado: 'conectado',
    lastSeen: new Date().toISOString(),
    topic: msg.topic
};

if (idx >= 0) {
    // Actualizar existente
    sensores[idx] = { ...sensores[idx], ...sensorData };
} else {
    // Añadir nuevo
    sensores.push(sensorData);
}

// Guardar
global.set('sensores_conectados', sensores);

// Notificar al dashboard si hay cambios
msg.topic = 'sensores';
msg.payload = sensores;
return msg;

let payload = msg.payload;
if(typeof payload === 'string') {
    try {
        payload = JSON.parse(payload);
    } catch(e) {}
}

const msgData = {
    topic: msg.topic,
    payload: payload,
    timestamp: new Date().toISOString(),
    date: new Date(),
    receivedAt: Date.now()
};

context.set('lastMessage_' + msg.topic, msgData);

let history = context.get('history_' + msg.topic) || [];
history.push(msgData);
if(history.length > 200) {
    history = history.slice(-200);
}
context.set('history_' + msg.topic, history);

msg.payload = msgData;
return msg;

// Solo procesar datos de esp32/emg_data
if (msg.topic !== 'esp32/emg_data') {
    return null;
}

const activeSession = flow.get('activeSession');
if (!activeSession) {
    return null;
}

let data;
try {
    data = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch(e) {
    return null;
}

if (data.emg === undefined) {
    return null;
}

// Actualizar estadísticas en memoria
let count = flow.get('emgCount') || 0;
let sum = flow.get('emgSum') || 0;
let max = flow.get('emgMax') || 0;
let min = flow.get('emgMin') || 999;

count++;
sum += data.emg;
max = Math.max(max, data.emg);
min = Math.min(min, data.emg);

flow.set('emgCount', count);
flow.set('emgSum', sum);
flow.set('emgMax', max);
flow.set('emgMin', min);

// Mensaje para actualizar stats UI
msg.stats = {
    count: count,
    average: sum / count,
    max: max,
    min: min,
    lastValue: data.emg
};

// Preparar para guardar en SQLite
msg.params = {
    $sesion_id: activeSession.id,
    $valor_emg: data.emg,
    $valor_crudo: data.raw || null,
    $voltaje: data.v || null
};

return msg;

const ip = msg.payload.ip || "192.168.4.100";
const cmd = msg.payload.command || "Check";

msg.url = `http://192.168.4.1/send?ip=${ip}&cmd=${cmd}`;
msg.payload = {
    ip: ip,
    command: cmd,
    url: msg.url,
    timestamp: new Date().toISOString()
};

return msg;

const response = {
    status: msg.statusCode === 200 ? 'SUCCESS' : 'ERROR',
    statusCode: msg.statusCode,
    response: msg.payload,
    timestamp: new Date().toISOString()
};

msg.payload = response;
return msg;

const topic = msg.topic;
const payload = msg.payload;

switch (topic) {
    case 'session/start':
        flow.set('activeSession', payload);
        flow.set('emgData', []);
        node.status({fill:'green', shape:'dot', text:'Sesión activa'});
        // Enviar comando al ESP32
        return [null, {topic: 'esp32/commands', payload: payload}, null];

    case 'session/stop':
        flow.set('activeSession', null);
        node.status({fill:'red', shape:'ring', text:'Sesión detenida'});

        // Guardar datos completos de la sesión
        flow.set('lastSessionData', payload);

        // Validar que persona_id existe
        if (!payload.persona_id) {
            node.error('❌ ERROR: persona_id es null o undefined');
            node.error('Payload completo: ' + JSON.stringify(payload));
            return [null, null, null];
        }

        // Preparar parámetros para insertar sesión (array para SQLite)
        msg.params = [
            parseInt(payload.persona_id),
            payload.nombre || (payload.persona_nombre + ' - ' + new Date().toLocaleDateString()),
            payload.fecha_inicio,
            payload.fecha_fin,
            'finalizada'
        ];

        return [msg, null, null];

    case 'persona/new':
        msg.params = [payload.nombre, payload.email || null, payload.telefono || null,  payload.descripcion || null];
        return [msg, null, null];

    case 'persona/delete':
        msg.params = [payload.id];
        return [msg, null, null];

    case 'sensores/request':
        // Devolver lista de sensores conectados
        let sensores = global.get('sensores_conectados') || [];
        if (sensores.length === 0) {
            sensores = [
                { id: 'ESP32_001', ip: '192.168.4.100', nombre: 'Sensor EMG 1', estado: 'desconocido' },
                { id: 'ESP32_002', ip: '192.168.4.101', nombre: 'Sensor EMG 2', estado: 'desconocido' }
            ];
        }
        return [null, null, { topic: 'sensores', payload: sensores, _uib: msg._uib }];

    case 'esp32/commands':
        // Reenviar comando MQTT al broker
        return [null, { topic: 'esp32/commands', payload: payload }, null];

    default:
        return [null, null, null];
}

msg.topic = 'sesiones';
msg.payload = msg.payload.map(s => ({
    ...s,
    persona_nombre: s.nombre || 'Sesión ' + s.id
}));
return msg;

const sessionData = flow.get('lastSessionData');

if (!sessionData) {
    node.error('No session data found');
    return null;
}

// Obtener el ID de la sesión recién insertada
let sessionId;
if (msg.payload && Array.isArray(msg.payload) && msg.payload[0] && msg.payload[0].id) {
    sessionId = msg.payload[0].id;
} else {
    node.error('❌ No se pudo obtener el ID de la sesión insertada');
    return null;
}

// Calcular duración en segundos
const inicio = new Date(sessionData.fecha_inicio);
const fin = new Date(sessionData.fecha_fin);
const duracion = Math.floor((fin - inicio) / 1000);

msg.params = [
    sessionId,
    sessionData.total_muestras || 0,
    sessionData.emg_promedio || 0,
    sessionData.emg_max || 0,
    sessionData.emg_min || 0,
    duracion
];

// Guardar para usar en el siguiente nodo
msg.sessionId = sessionId;
msg.sessionData = sessionData;

return msg;

const sessionId = msg.sessionId;
const sessionData = msg.sessionData;

if (!sessionData.datos || sessionData.datos.length === 0) {
    node.warn('No EMG data to save');
    return null;
}

// Preparar datos EMG para inserción por lotes
const datos = sessionData.datos.map((emg, index) => {
    return {
        sesion_id: sessionId,
        valor_emg: emg,
        valor_crudo: emg,
        voltaje: null
    };
});

msg.datos = datos;
msg.sessionId = sessionId;

return msg;

const datos = msg.datos;
const sessionId = msg.sessionId;

if (!datos || datos.length === 0) {
    node.warn('⚠️ No hay datos EMG para guardar');
    return null;
}

// Crear un mensaje por cada dato EMG
const msgs = [];

for (const dato of datos) {
    msgs.push({
        params: [
            dato.sesion_id,
            dato.valor_emg,
            dato.valor_crudo,
            dato.voltaje
        ],
        sessionId: sessionId,
        totalDatos: datos.length
    });
}

return [msgs];

const activeSession = flow.get('activeSession');
if (!activeSession) return null;

const data = msg.payload;
if (!data || data.emg === undefined) return null;

// Guardar en array temporal
let emgData = flow.get('emgData') || [];
emgData.push(data.emg);
flow.set('emgData', emgData);

// Enviar a UI
msg.topic = 'emg_data';
msg.payload = data.emg;

return msg;

// Formatear clientes del ESP32 para el frontend
if (!msg.payload || !msg.payload.clients) {
    return null;
}

msg.topic = 'sensores';
return msg;

// Reenviar respuestas del ESP32 a UIBuilder
msg.topic = 'esp32/responses';
return msg;

const id = parseInt(msg.req.params.id);
if (isNaN(id)) {
    msg.payload = { error: 'Invalid session ID' };
    return [null, msg];
}
msg.params = [id];
return msg;

// Extraer solo los valores EMG para el gráfico
const emgValues = msg.payload.map(d => d.valor_emg);
const fullData = msg.payload;

msg.payload = {
    sesion_id: msg.req.params.id,
    total: fullData.length,
    emg_values: emgValues,
    datos: fullData
};
return msg;

// Obtener sensores del contexto global o devolver lista por defecto
let sensores = global.get('sensores_conectados') || [];

// Si no hay sensores registrados, devolver lista de ejemplo
if (sensores.length === 0) {
    sensores = [
        { id: 'ESP32_001', ip: '192.168.4.100', nombre: 'Sensor EMG 1', estado: 'desconocido' },
        { id: 'ESP32_002', ip: '192.168.4.101', nombre: 'Sensor EMG 2', estado: 'desconocido' }
    ];
}

msg.payload = sensores;
return msg;
